 void LoadActiveIconPack(){activeIconPack=null;activeIconPackFolder="";try{if(String.IsNullOrWhiteSpace(cfg.IconPack))return;string folder=Path.Combine(InstalledIconPackFolder,SafeIconPackId(cfg.IconPack)),file=Path.Combine(folder,"icons.json");if(!File.Exists(file)){cfg.IconPack="";return;}var manifest=new JavaScriptSerializer().Deserialize<AwlIconPackManifest>(File.ReadAllText(file));if(manifest==null)throw new InvalidDataException("Invalid icons.json");manifest.Apps=manifest.Apps??new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);manifest.Icons=manifest.Icons??new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);activeIconPack=manifest;activeIconPackFolder=folder;}catch(Exception error){Log("Icon pack: "+error.Message);cfg.IconPack="";}}
