 ImageSource IconPackSvgImage(string file){try{var geometry=IconPackGeometry(file);if(geometry==null)return null;Rect bounds=geometry.Bounds;if(bounds.Width<1||bounds.Height<1)return null;double scale=80/Math.Max(bounds.Width,bounds.Height);var visual=new DrawingVisual();using(var context=visual.RenderOpen()){context.PushTransform(new TranslateTransform(48-(bounds.X+bounds.Width/2)*scale,48-(bounds.Y+bounds.Height/2)*scale));context.PushTransform(new ScaleTransform(scale,scale));context.DrawGeometry(Brushes.White,new Pen(Brushes.White,1.5/scale),geometry);context.Pop();context.Pop();}var bitmap=new RenderTargetBitmap(96,96,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);bitmap.Freeze();return bitmap;}catch{return null;}}
