 string LocalIconPackPackage(AwlCatalogItem item){string relative=item==null?"":item.downloadUrl??"";if(String.IsNullOrWhiteSpace(relative)||Uri.IsWellFormedUriString(relative,UriKind.Absolute))return "";string clean=relative.Replace('/',Path.DirectorySeparatorChar);foreach(string root in new[]{Path.Combine(DevProjectRoot(),"icon-packs"),Path.Combine(InstallRoot,"icon-packs")}){string candidate=Path.Combine(root,clean);if(File.Exists(candidate))return candidate;}return "";}
