 async void InstallIconPackCatalog(AwlCatalogItem item,Action<double> progress=null,Action completed=null){string package=LocalIconPackPackage(item),temporary="";try{if(progress!=null)progress(0);if(String.IsNullOrWhiteSpace(package)){string url=IconPackPackageUrl(item);if(String.IsNullOrWhiteSpace(url))throw new InvalidDataException("This icon pack has no package URL.");temporary=Path.Combine(Path.GetTempPath(),"Awl-icon-pack-"+Guid.NewGuid().ToString("N")+".iconpack");using(var client=new WebClient()){client.Headers.Add(HttpRequestHeader.UserAgent,"Awl/"+BuildInfo.Version);client.DownloadProgressChanged+=delegate(object sender,DownloadProgressChangedEventArgs e){if(progress!=null)progress(Math.Min(90,e.ProgressPercentage*.9));};await client.DownloadFileTaskAsync(new Uri(url),temporary);}package=temporary;}if(progress!=null)progress(94);AwlIconPackManifest manifest;ExtractIconPack(package,out manifest);ActivateIconPack(manifest);if(progress!=null)progress(100);if(completed!=null)completed();MessageBox.Show(launcher,"Installed "+(String.IsNullOrWhiteSpace(manifest.name)?manifest.id:manifest.name)+".","Icon pack installed");}catch(Exception error){MessageBox.Show(launcher,error.Message,"Icon pack could not be installed");}finally{if(!String.IsNullOrWhiteSpace(temporary))try{File.Delete(temporary);}catch{}}}
 ImageSource IconPackCatalogImage(AwlCatalogItem item,string name,int decode=160){try{if(item==null||String.IsNullOrWhiteSpace(name))return null;string installed=Path.Combine(InstalledIconPackFolder,SafeIconPackId(item.id),name);if(File.Exists(installed))return FileImage(installed,decode);string package=LocalIconPackPackage(item);if(String.IsNullOrWhiteSpace(package))return null;string cacheFolder=Path.Combine(IconPackFolder,"CatalogImages");Directory.CreateDirectory(cacheFolder);string target=Path.Combine(cacheFolder,SafeIconPackId(item.id)+"-"+name);if(!File.Exists(target)||File.GetLastWriteTimeUtc(target)<File.GetLastWriteTimeUtc(package)){using(var zip=ZipFile.OpenRead(package)){var entry=zip.GetEntry(name);if(entry==null)return null;using(var input=entry.Open())using(var output=File.Create(target)){input.CopyTo(output);}}}return FileImage(target,decode);}catch{return null;}}
  AwlIconPackCatalog LoadIconPackCatalog(){var catalog=new AwlIconPackCatalog();foreach(string file in new[]{Path.Combine(IconPackFolder,"catalog.json"),Path.Combine(DevProjectRoot(),"icon-packs","catalog.json"),Path.Combine(InstallRoot,"icon-packs","catalog.json")})try{if(File.Exists(file)){catalog=new JavaScriptSerializer().Deserialize<AwlIconPackCatalog>(File.ReadAllText(file))??catalog;catalog.items=catalog.items??new List<AwlCatalogItem>();return catalog;}}catch(Exception error){Log("Icon pack catalog: "+error.Message);}return catalog;}
