 public string IconPackSelfTest(){string folder=Path.Combine(Path.GetTempPath(),"Awl-icon-pack-"+Guid.NewGuid().ToString("N")),id="self-test-icon-pack";try{Directory.CreateDirectory(Path.Combine(folder,"Icons"));File.WriteAllText(Path.Combine(folder,"Icons","motion.svg"),"<svg><path d=\"M2,2 L22,22\" /></svg>");var manifest=new AwlIconPackManifest{id=id,Icons=new Dictionary<string,string>{{"startmenu-interface-motion-main","Icons/motion.svg"}},Apps=new Dictionary<string,string>{{"discord","Icons/motion.svg"}}};File.WriteAllText(Path.Combine(folder,"icons.json"),new JavaScriptSerializer().Serialize(manifest));File.WriteAllBytes(Path.Combine(folder,"icon.png"),new byte[]{137,80,78,71});string package=folder+".iconpack";ZipFile.CreateFromDirectory(folder,package);AwlIconPackManifest installed;ExtractIconPack(package,out installed);string asset=Path.Combine(InstalledIconPackFolder,id,"Icons","motion.svg");if(installed.id!=id||!File.Exists(asset)||IconPackGeometry(asset)==null)return "FAILED: icon pack package extraction";return "Icon packs use semantic IDs, safe asset paths, and optional application replacements";}catch(Exception error){return "FAILED: icon pack "+error.Message;}finally{try{Directory.Delete(folder,true);File.Delete(folder+".iconpack");Directory.Delete(Path.Combine(InstalledIconPackFolder,id),true);}catch{}}}
